        }

        clearActiveCard()
        void runCardEdit(() => dataService.cards.moveCard(path, drop.targetStatus, drop.targetIndex), `Card move failed: ${path}`)
    }, [clearActiveCard, states])

    const handleOpenInFileMode = (path: string) => {
        cardPopupService.closeCardDetails()
        workspaceViewService.selectPath(path)
        void runCardEdit(() => openFilesService.openPath(path), `File open failed: ${path}`)
        workspaceViewService.setViewMode('text')
        telemetryService.trackEvent('navigation')
    }

    const handleArchiveCard = async (path: string) => {
        try {
            const activeCards = dataService.getState().snapshot?.activeCards ?? []
            const card = activeCards.find((candidate) => candidate.path === path)
            if (!card?.header.internalId) throw new Error(`Cannot archive card without an internal ID: ${path}`)
            const targetIndex = activeCards.filter((candidate) => candidate.header.status === 'archived').length
            await dataService.cards.moveCard(path, 'archived', targetIndex)
            workspaceViewService.clearSelectedPath(path)
            cardPopupService.closeCardDetailsByInternalId(card.header.internalId)
            if (openAffectsPath === path) handleCloseAffects()
        } catch (error) {
            dialogService.error(error, { fallbackMessage: `Card archive failed: ${path}` })
            throw error
        }
    }

    const handleDeleteCard = async (path: string) => {
        try {
            const card = dataService.getState().snapshot?.activeCards.find((candidate) => candidate.path === path)
            if (!card?.header.internalId) throw new Error(`Cannot delete card without an internal ID: ${path}`)
            await dataService.cards.deleteCard(path)
            workspaceViewService.clearSelectedPath(path)
            cardPopupService.closeCardDetailsByInternalId(card.header.internalId)
            if (openAffectsPath === path) handleCloseAffects()
        } catch (error) {
            dialogService.error(error, { fallbackMessage: `Card delete failed: ${path}` })
            throw error
        }
    }

    const handleTitleChange = (path: string, title: string) => {
        dataService.cards.updateCardTitle(path, title).catch((error: unknown) => {
            dialogService.error(error, { fallbackMessage: `Title update failed: ${path}` })
        })
    }

    const handleTogglePolicy = (path: string, policyKey: string) => {
        void runCardEdit(() => dataService.cards.toggleCardPolicy(path, policyKey), `Policy toggle failed: ${path}`)
    }

    const handleAffectsChange = (path: string, affects: string[]) => {
        void runCardEdit(() => dataService.cards.updateCardAffects(path, affects), `Affects update failed: ${path}`)
    }

    return (
        <Box
            ref={rootElementRef}
            sx={{ bgcolor: 'background.default', display: 'flex', flex: 1, minHeight: 0, overflow: 'hidden', position: 'relative' }}
        >
            <DndContext
                collisionDetection={closestCorners}
                onDragCancel={clearActiveCard}
                onDragEnd={handleDragEnd}
                onDragOver={handleDragOver}
                onDragStart={handleDragStart}
                sensors={sensors}
            >
                <Box
                    aria-label="Card columns"
                    sx={{

import { createCardFile } from '../../data/card_naming'

                sentryOrganization: request.organization.trim(),
            })
            preparedFiles.push({ ...file, content })
            identities.add(identity)
        }

        if (preparedFiles.length === 0) return []
        if (this.context.dependencies.project()?.id !== request.projectId) {
            throw new Error('Opened project changed before Sentry import persistence')
        }

        this.context.dependencies.updateFiles(preparedFiles, [], config.workingFolder)
        await this.context.commitCreatedFiles({
            branch: project.branch,
            files: preparedFiles,
            message: `Import ${preparedFiles.length} Sentry issue${preparedFiles.length === 1 ? '' : 's'}`,
        })
        void this.context.pushCreatedItem('Sentry issues')

        return preparedFiles
    }

    savePastedImageForCard(cardPath: string, file: File) {
        return this.images.saveForCard(cardPath, file)
    }

    savePastedImageForNewCard(file: File) {
        return this.images.saveForNewCard(file)
    }

    deletePastedImage(path: string) {
        return this.images.delete(path)
    }

    copyAttachmentsForCard(cardPath: string, files: File[]) {

        this.state = { ...this.state, isCommitting: true }
        this.dispatchChanged()

        try {
            await this.withLoading('Commit failed', () => projectPersistenceService.flushPendingChanges())
        } finally {
            this.state = { ...this.state, isCommitting: false }
            this.dispatchChanged()
        }
    }

    async pull() {
        projectAccessService.requireWritable()
        this.state = { ...this.state, isPulling: true }
        this.dispatchChanged()

        try {
            await this.withLoading('Pull failed', () => dataService.projectLoading.pull())
        } finally {
            this.state = { ...this.state, isPulling: false }
            this.dispatchChanged()
        }
    }

    discardGithubPendingCommits(project: ProjectReference, accessToken: string | null) {
        projectAccessService.requireWritable()
        const storage = createGithubStorage(accessToken)
        storage.discardPendingCommits(project)
        this.state = { ...this.state, errorMessage: null, pendingGithubConflictProject: null }
        this.dispatchChanged()
    }

    async getReleaseBranchCandidates() {
        return this.withLoading('Release preparation failed', () => dataService.releases.getReleaseBranchCandidates())
    }

    async completeRelease(releaseName: string, selectedBranchNames: string[]) {
        projectAccessService.requireWritable()
        await this.withLoading(
            'Release completion failed',
            () => dataService.releases.completeRelease(releaseName, selectedBranchNames),
        )
    }

    async createCard(draft: CardDraft, initialState: string) {
        projectAccessService.requireWritable()
        this.setCardCreationState(true)
        if (this.state.errorMessage !== null) this.setError(null)

        try {
            await this.waitForNewCardImageSaves()
            await dataService.cards.createCard(draft, initialState)
            this.newCardAttachmentPaths.clear()
            this.newCardImagePaths.clear()
        } catch (error) {
            const message = error instanceof Error ? error.message : 'Card creation failed'
            this.state = { ...this.state, errorMessage: message, pendingGithubConflictProject: null }
            this.dispatchChanged()
            if (!isProjectLoadErrorReported(error)) dialogService.error(error, { fallbackMessage: 'Card creation failed' })
            throw error
        } finally {
            this.setCardCreationState(false)
        }
    }

    private setCardCreationState(isCreatingCard: boolean) {
        if (this.cardCreationState.isCreatingCard === isCreatingCard) return

        this.cardCreationState = { isCreatingCard }
        this.dispatchEvent(new CustomEvent<CardCreationState>('cardCreationChanged', { detail: this.cardCreationState }))
    }

    private async saveAndInsertNewCardImage(file: File, insertMarkdown: (markdown: string) => void) {
        const savedImage = await dataService.cards.savePastedImageForNewCard(file)
        this.newCardImagePaths.add(savedImage.path)
        try {
            insertMarkdown(`![pasted image](<${savedImage.fileName}>)`)
        } catch (error) {
            try {
                await dataService.cards.deletePastedImage(savedImage.path)
                this.newCardImagePaths.delete(savedImage.path)
            } catch (cleanupError) {
                dialogService.error(cleanupError, { fallbackMessage: `Could not remove ${savedImage.path}` })
            }
            throw error
        }
    }

    private setReadOnly(isReadOnly: boolean) {
        this.projectAccess.setReadOnly(isReadOnly)
    }

    private async withProjectLoading<T>(fallbackMessage: string, operation: () => Promise<T>): Promise<T> {
        this.state = { ...this.state, isProjectLoading: true }
        this.dispatchChanged()

        try {
            return await this.withLoading(fallbackMessage, operation)
        } finally {
            this.state = { ...this.state, isProjectLoading: false }

import { Box, Chip, IconButton, Paper, Tooltip, Typography } from '@mui/material'
import { SortableContext, verticalListSortingStrategy } from '@dnd-kit/sortable'
import Plus from 'mdi-material-ui/Plus'
import { useCallback, useSyncExternalStore } from 'react'
import type { ReactNode } from 'react'
import type { CardTypeConfig } from '../../data/data_types'
import { requestOpenNewCardDialog } from '../project_command_events'
import { CardColumnEndDropTarget } from './card_column_end_drop_target'
import { cardDragDropService } from './card_drag_drop_service'
import { CardView, type CardHandlers } from './project_card_view'
import type { VisibleCardColumn } from './use_card_view_columns'
import { useCardColumnCards } from './use_card_column_cards'
import { useProjectReadOnly } from '../hooks/use_project_read_only'

const MIN_COLUMN_WIDTH = 200
const MAX_COLUMN_WIDTH = 320

interface CardColumnProps extends CardHandlers {
    cardTypes: CardTypeConfig[]
    column: VisibleCardColumn
    isMobile: boolean
}

/** One status column: a polished droppable stack with header metadata and an empty target. */
export function CardColumn(props: CardColumnProps) {
    const {
        cardTypes, column, isMobile,
        ...handlers
    } = props
    const cardPaths = useCardColumnCards(column.status)
    const readOnly = useProjectReadOnly()
    const subscribe = useCallback(
        (listener: () => void) => cardDragDropService.subscribeColumn(column.status, listener),
        [column.status],
    )
    const getSnapshot = useCallback(
        () => cardDragDropService.getColumnPreview(column.status),
        [column.status],
    )
    const dropPreview = useSyncExternalStore(subscribe, getSnapshot, getSnapshot)
    const dropPreviewHeight = dropPreview?.dropPreviewHeight ?? null
    const dropPreviewIndex = dropPreview?.dropPreviewIndex ?? null
    const columnLabel = column.status || 'Unassigned'
